def get_color_spread(grid, color):
    """Get for each row: (min_col, max_col) where color appears"""
    rows_with_color = {}
    for r in range(len(grid)):
        cols = [c for c in range(len(grid[0])) if grid[r][c] == color]
        if cols:
            rows_with_color[r] = (min(cols), max(cols), len(set(cols)))
    return rows_with_color

def is_coherent(rows_with_color, threshold_rows=2, threshold_same_col=5):
    """
    A color is coherent if it appears in threshold_rows+ consecutive rows
    and the column range width is reasonable
    """
    if len(rows_with_color) < threshold_rows:
        return False

    rows = sorted(rows_with_color.keys())

    # Check if rows are reasonably consecutive (within threshold_rows)
    for i in range(threshold_rows):
        if rows[i+1] - rows[i] > 1:
            # Gaps - but that's okay if the pattern is still coherent
            pass

    # Check the column spread - should be relatively wide
    for r, (minc, maxc, cs) in rows_with_color.items():
        if maxc - minc < threshold_same_col or cs < threshold_same_col:
            return False

    return True

